    caseContext:
      "62歳女性。身長148 cm、体重68 kg。糖尿病のため、食事療法及び運動療法に加え、処方1による治療を受けていたが、効果不十分のため処方2による治療に変更された。\n\n（処方1）\nミチグリニドカルシウム水和物10 mg　1回1錠（1日3錠）\nミグリトール錠50 mg　1回1錠（1日3錠）\n1日3回　朝昼夕食直前　28日分\n\n（処方2）\nリラグルチド（遺伝子組換え）皮下注（18 mg/シリンジ）　1回0.9 mg\n1日1回　朝　皮下注射　1本（20回分）",
    field: "実務",

    question:
      "62歳女性。身長148 cm、体重68 kg。糖尿病のため、食事療法及び運動療法に加え、処方1による治療を受けていたが、効果不十分のため処方2による治療に変更された。\n\n（処方1）\nミチグリニドカルシウム水和物10 mg 1回1錠（1日3錠）\nミグリトール錠50 mg 1回1錠（1日3錠）\n1日3回 朝昼夕食直前 28日分\n\n（処方2）\nリラグルチド（遺伝子組換え）皮下注（18 mg/シリンジ）1回0.9 mg\n1日1回 朝 皮下注射 1本（20回分）\n\nリラグルチドによる治療に関する記述のうち、正しいのはどれか。2つ選べ。",

