      "生後11ヶ月男児。約2週間前より体に発赤や湿疹が多数出現し、小児科を受診した。その結果、食物によるアトピー性皮膚炎と診断され、薬物治療とともに原因食物除去も医師より提案された。母親が処方せんを保険薬局に持参し、薬剤師に薬物治療のみならず日常の食事や生活の注意点についても相談した。\n\n食物アレルギー原因食品とその表示に関する記述のうち、正しいのはどれか。2つ選べ。",

    choices: [
    "乳児期の食物アレルギーの原因食品として最も多いのは、大豆である。",
    "鶏卵中の食物アレルギーの主な原因物質は、卵黄に存在するタンパク質である。",
    "食品中のアレルギー物質の表示は、「農林物資の規格化及び品質表示の適正化に関する法律」（JAS法）に定められている。",
    "落花生は重篤な症状を引き起こし、生命に関わることもあるので、特定原材料に指定されている。",
    "小麦に関しては、キャリーオーバーの場合でも、表示が義務づけられる。"
    ],

    answer: [3, 4],


    explanation:
      "正答は4、5です。落花生はアナフィラキシーなど重篤な症状を起こしやすく、特定原材料として表示が義務づけられます。また、小麦も特定原材料であり、原材料として明記されないキャリーオーバーの場合でも、アレルギー表示の対象になります。1は、乳児期の原因食品として多いのは鶏卵、牛乳、小麦などで、大豆が最も多いわけではありません。2は、鶏卵の主なアレルゲンは卵白中のタンパク質（オボムコイドなど）です。3は、アレルギー表示はJAS法ではなく、食品衛生法や現在の食品表示法に基づく食品表示基準で扱われます。"
