      "身近な家庭用品に含まれる化学物質には、健康への影響があり法律による規制を受けるものがある。下着、靴下などのしわや縮みを防ぐために樹脂加工剤が使用される。この樹脂加工剤に由来し、ヒトの健康に影響を与える化学物質としてこれらの繊維製品に含まれる可能性がある。",
