    "バルプロ酸の副作用リスクが高まるため、肝機能検査を実施すべきである。",
    "ビフィズス菌錠は、耐性乳酸菌錠に変更すべきである。",
    "アンピシリンは、バルプロ酸との相互作用により中枢性けいれんを誘発するので、併用禁忌である。"
