      "この患児に、バルプロ酸ナトリウムシロップ5％が、前問で設定した1日投与量で1日2回、30日分処方された。調剤する際に、1回服用量が整数mLになるように、単シロップを用いて最小限の賦形を行うことにした。内用液剤容器の容量（mL）として、最も適切な容器を1つ選べ。ただし、内用液剤容器の選択は、薬剤の総量を超えた最小の容量のものを選択する。",

